import json,re
msgs=[]
for line in lines:
 d=json.loads(line)
 if d.get('type')=='message' and d['message'].get('role')=='user':
  txt=''.join(x.get('text','') for x in d['message'].get('content',[]) if 'text' in x)
  if 'Demos received' in txt: msgs.append(txt)
print(len(msgs), [len(x) for x in msgs])

def get_pair(txt):
 m=re.search(r'Demo pair \d+ input \(13x14\):\n(.*?)\nDemo pair \d+ output \(13x14\):\n(.*?)\n\nSame instance',txt,re.S)
 def grid(s): return [[int(v) for v in l.split()] for l in s.strip().splitlines()]
 return grid(m.group(1)),grid(m.group(2))
pairs=[get_pair(t) for t in msgs]
for i,(x,y) in enumerate(pairs):
 print(i, [[int(x[r][c]==0) for c in [1,4,7,10,13]] for r in [1,3,5,7,9,11]])
 print('out',[[int(y[r][c]==0) for c in [1,4,7,10,13]] for r in [1,3,5,7,9,11]])
